package spms.service;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PasswordServiceTest {@Test void verifiesOnlyTheOriginalPassword(){char[] password="Demo@12345".toCharArray();String hash=PasswordService.hash(password);assertNotEquals("Demo@12345",hash);assertTrue(PasswordService.verify("Demo@12345".toCharArray(),hash));assertFalse(PasswordService.verify("wrong".toCharArray(),hash));}@Test void verifiesHashedSqlDemoCredentials(){assertTrue(PasswordService.verify("Admin@123".toCharArray(),"pbkdf2$a5At1d47w9+pIPj3AmTRGg==$oMF/qHKPWWK6Er09R/sqnAXUjk87rjMQU6CzppisoEY="));assertTrue(PasswordService.verify("Hr@123".toCharArray(),"pbkdf2$XK+l2pxBZkcHhN2yvXtvVQ==$BVwB1NYTiqK8byasxAy+bx3/MTGNAdnD3BTyto/u034="));assertTrue(PasswordService.verify("Employee@123".toCharArray(),"pbkdf2$XS6r5panUdu+th+NkBP7XA==$JkQuHVHZP3WGqZYS9RZX6dwjHSaKhQr91RLXkCn8d1Y="));}}
